export function ogHeroSrcSet(locale: string, slug: string): string {
  const src = ogThumb(locale, slug)
  const k = src.slice('/og/'.length).split('.png')[0]
  return src && OG_2X[k] ? `${src} 1200w, /og/${k}-2x.webp?v=${OG_2X[k]} 2400w` : ''
}

